import fs from 'node:fs';
import path from 'node:path';

const [input, output] = process.argv.slice(2);
if (!input || !output) throw new Error('Usage: node install-page.mjs <release.json> <output.html>');
const release = JSON.parse(fs.readFileSync(input, 'utf8'));
const repository = process.env.GITHUB_REPOSITORY ?? '';
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);
const assets = Array.isArray(release.assets) ? release.assets : [];
const installers = (extension) => assets.filter((asset) => String(asset.name).toLowerCase().endsWith(extension));
const mac = installers('.dmg');
const windows = installers('.exe');
const version = String(release.name || release.tag_name || 'Production').replace(/^Dashboard\s+v/i, '').replace(/^dashboard-v/i, '');
const published = release.published_at ? new Intl.DateTimeFormat('en', { dateStyle: 'long' }).format(new Date(release.published_at)) : '';
const downloadLabel = (asset, platform) => platform === 'windows' ? 'Download installer' : /arm64|aarch64|apple[-_ ]?silicon/i.test(asset.name) ? 'Download for Apple Silicon' : /x64|x86_64|intel/i.test(asset.name) ? 'Download for Intel Mac' : 'Download DMG';
const download = (platformAssets, platform, detail, instructions) => platformAssets.length ? `
    <article class="download-card" data-platform="${platform}">
      <div class="platform-mark" aria-hidden="true">${platform === 'macos' ? '⌘' : '⊞'}</div>
      <div class="download-copy"><p class="eyebrow">${platform === 'macos' ? 'macOS' : 'Windows'}</p><h2>${platform === 'macos' ? 'Install on Mac' : 'Install on Windows'}</h2><p>${detail}</p></div>
      <div class="download-actions">${platformAssets.map((asset) => `<a class="download-button" href="${escapeHtml(asset.browser_download_url)}">${downloadLabel(asset, platform)}</a>`).join('')}</div>
      <ol>${instructions.map((step) => `<li>${escapeHtml(step)}</li>`).join('')}</ol>
    </article>` : '';
const otherAssets = assets.filter((asset) => !mac.includes(asset) && !windows.includes(asset) && /\.(?:zip)$/i.test(asset.name));
const releaseUrl = release.html_url || (repository ? `https://github.com/${repository}/releases/latest` : '#');
const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="Download and install the production release of HayHay Dev Tools.">
<title>Install HayHay Dev Tools</title><style>
:root{color-scheme:dark;--bg:#101217;--surface:#191c23;--surface-2:#20242d;--border:#303642;--text:#f1f4f8;--muted:#9ca6b5;--accent:#4a82bd;--accent-2:#6aa7e5;--success:#4cc38a;--shadow:rgba(0,0,0,.42)}*{box-sizing:border-box}body{margin:0;min-height:100vh;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--text);background:radial-gradient(circle at 50% -20%,#243f61 0,transparent 42%),var(--bg)}a{color:inherit}.shell{width:min(1040px,calc(100% - 32px));margin:auto;padding:72px 0 48px}.hero{text-align:center;max-width:720px;margin:0 auto 42px}.brand{display:inline-grid;width:76px;height:76px;place-items:center;margin-bottom:22px;border:1px solid rgba(255,255,255,.14);border-radius:22px;background:linear-gradient(145deg,#eef1f5,#fff);color:#202226;box-shadow:0 18px 50px var(--shadow);font-size:31px;font-weight:900;letter-spacing:-5px}.hero .eyebrow,.download-card .eyebrow{margin:0 0 8px;color:var(--accent-2);font-size:12px;font-weight:750;letter-spacing:.12em;text-transform:uppercase}.hero h1{margin:0;font-size:clamp(34px,7vw,58px);line-height:1.05;letter-spacing:-.045em}.hero>p{margin:18px auto 0;color:var(--muted);font-size:17px;line-height:1.65}.release-meta{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin-top:22px}.release-meta span{padding:6px 10px;border:1px solid var(--border);border-radius:999px;background:rgba(25,28,35,.72);color:var(--muted);font-size:12px}.release-meta strong{color:var(--text)}.downloads{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,390px),1fr));gap:18px}.download-card{display:grid;grid-template-columns:48px 1fr;gap:0 15px;padding:24px;border:1px solid var(--border);border-radius:18px;background:linear-gradient(155deg,rgba(32,36,45,.98),rgba(22,25,32,.98));box-shadow:0 18px 50px rgba(0,0,0,.18)}.download-card.is-recommended{border-color:var(--accent);box-shadow:0 18px 54px rgba(74,130,189,.18)}.platform-mark{display:grid;width:48px;height:48px;place-items:center;border-radius:13px;background:var(--surface-2);font-size:24px}.download-copy h2{margin:0;font-size:22px}.download-copy>p:last-child{min-height:42px;margin:8px 0 0;color:var(--muted);line-height:1.5}.download-actions{grid-column:1/-1;display:grid;gap:8px;margin-top:22px}.download-button{display:flex;justify-content:center;padding:13px 18px;border-radius:9px;background:var(--accent);font-weight:750;text-decoration:none;transition:background .15s,transform .15s}.download-button:hover{background:var(--accent-2);transform:translateY(-1px)}.download-button:focus-visible,.footer a:focus-visible{outline:3px solid rgba(106,167,229,.45);outline-offset:3px}.download-card ol{grid-column:1/-1;margin:20px 0 0;padding:18px 18px 0 36px;border-top:1px solid var(--border);color:var(--muted);line-height:1.55}.download-card li+li{margin-top:7px}.empty{padding:30px;border:1px solid var(--border);border-radius:18px;background:var(--surface);text-align:center;color:var(--muted)}.other{margin-top:18px;padding:18px 22px;border:1px solid var(--border);border-radius:13px;background:rgba(25,28,35,.75)}.other h2{margin:0 0 10px;font-size:15px}.other-links{display:flex;gap:10px;flex-wrap:wrap}.other a,.footer a{color:var(--accent-2)}.footer{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:28px;padding-top:22px;border-top:1px solid var(--border);color:var(--muted);font-size:12px}@media(max-width:560px){.shell{padding-top:42px}.download-card{padding:20px}.footer{flex-direction:column}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><main class="shell"><header class="hero"><div class="brand" aria-hidden="true">‹H›</div><p class="eyebrow">Production release</p><h1>HayHay Dev Tools</h1><p>Download the signed production installer for your computer. Future updates are delivered automatically through the same verified release channel.</p><div class="release-meta"><span>Version <strong>${escapeHtml(version)}</strong></span>${published ? `<span>Published <strong>${escapeHtml(published)}</strong></span>` : ''}<span><strong>Production</strong></span></div></header>
<section class="downloads" aria-label="Production installers">${download(mac, 'macos', 'Signed and notarized for supported Apple Silicon and Intel Macs.', ['Choose the installer for your Mac processor, then open the DMG.', 'Drag HayHay Dev Tools into Applications.', 'Open it from Applications.'])}${download(windows, 'windows', 'Signed Windows installer with automatic update support.', ['Download and run the installer.', 'Approve the verified publisher prompt.', 'Launch HayHay Dev Tools from the Start menu.'])}${!mac.length && !windows.length ? '<div class="empty">Production installers are not available yet. Check the release page for the current publishing status.</div>' : ''}</section>
${otherAssets.length ? `<section class="other"><h2>Other downloads</h2><div class="other-links">${otherAssets.map((asset) => `<a href="${escapeHtml(asset.browser_download_url)}">${escapeHtml(asset.name)}</a>`).join('')}</div></section>` : ''}
<footer class="footer"><span>Installers are published from the selected immutable production release.</span><a href="${escapeHtml(releaseUrl)}">View release details on GitHub</a></footer></main>
<script>const platform=/Mac/i.test(navigator.platform)?'macos':/Win/i.test(navigator.platform)?'windows':'';if(platform)document.querySelector('[data-platform="'+platform+'"]')?.classList.add('is-recommended');</script></body></html>`;
fs.mkdirSync(path.dirname(output), { recursive: true }); fs.writeFileSync(output, html);
